-- Independent directory, deliberately never a service_center/partner record.
create table sto_directory_sites (
 id text primary key check (id ~ '^directory:[a-z0-9-]+$'),
 name text not null, address text not null, phone text not null check(phone ~ '^\+7[0-9]{10}$'),
 category text not null check(category in ('sto','tyre','wash','refrigeration','trailer')),
 lat double precision, lng double precision,
 services jsonb not null check(jsonb_typeof(services)='array'),
 hours text, source text not null check(source ~ '^https?://'),
 state text not null default 'draft' check(state in ('draft','published','hidden')),
 source_reuse_checked boolean not null default false,
 location_checked boolean not null default false,
 reviewed_by uuid references users(id) on delete set null,
 reviewed_at timestamptz,
 revision integer not null default 1,
 updated_at timestamptz not null default now(),
 check ((lat is null and lng is null) or (lat is not null and lng is not null and lat between -85 and 85 and lng between -180 and 180 and not(lat=0 and lng=0))),
 check(state<>'published' or (lat is not null and lng is not null and source_reuse_checked and location_checked and reviewed_at is not null))
);
create index sto_directory_public_idx on sto_directory_sites(state,id);
create table sto_directory_feedback(
 site_id text not null references sto_directory_sites(id) on delete cascade,
 user_id uuid not null references users(id) on delete cascade,
 verdict text not null check(verdict in ('working','not_working')),
 updated_at timestamptz not null default now(),
 primary key(site_id,user_id)
);
-- Seed 40 review candidates only. No automatic publication or customer calls.
on conflict(id) do nothing;
